function buildMenubar(){const m=$('#menus');m.innerHTML='';MENUS.forEach(([t,items],i)=>{const el=h('div',{class:'mtop',tabindex:0},t);el.onclick=e=>{if(menuOpenIdx===i){closeMenus();return}openTopMenu(i,el)};el.onmouseenter=()=>{if(menuOpenIdx>=0&&menuOpenIdx!==i)openTopMenu(i,el)};m.append(el)})}
function openTopMenu(i,el){closeMenus();menuOpenIdx=i;el.classList.add('open');const r=el.getBoundingClientRect();showMenuAt(MENUS[i][1](),r.left,r.bottom,true)}
function showMenuAt(items,x,y,keepIdx,level=0){if(!keepIdx&&level===0)closeMenus();const d=h('div',{class:'dropdown','data-level':level});for(const it of items){if(it==='-'){d.append(h('div',{class:'msep'}));continue}const en=!it.en||it.en();const row=h('div',{class:'mi'+(en?'':' dis')+(it.sub?' sub':'')+(it.chk&&it.chk()?' chk':'')},h('span',null,it.label),it.sc?h('span',{class:'sc'},it.sc):null);if(it.sub){row.onmouseenter=()=>{$$(`.dropdown[data-level="${level+1}"]`).forEach(x=>x.remove());if(!en)return;const r=row.getBoundingClientRect();showMenuAt(it.sub,r.right-2,r.top-4,true,level+1)}}else{row.onmouseenter=()=>$$(`.dropdown[data-level="${level+1}"]`).forEach(x=>x.remove());if(en)row.onclick=()=>{closeMenus();it.fn&&it.fn()}}d.append(row)}document.body.append(d);const r=d.getBoundingClientRect();d.style.left=Math.max(0,Math.min(x,innerWidth-r.width-4))+'px';d.style.top=Math.max(0,Math.min(y,innerHeight-r.height-4))+'px';if(!openPop)openPop=d;return d}
function closeMenus(){$$('.dropdown,.flyout').forEach(x=>x.remove());$$('.mtop.open').forEach(x=>x.classList.remove('open'));menuOpenIdx=-1;openPop=null}
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.dropdown,.flyout,.mtop'))closeMenus()},true);

