function renderTabs(){const t=$('#tabs');t.innerHTML='';for(const d of docs){const al=d.active?d.active.name:'';const el=h('div',{class:'dtab'+(d===doc?' on':''),title:d.name+' · 끌어서 순서 바꾸기','data-doc':d.id,draggable:'true'},`${d.name} @ ${zpct(d.zoom)} (${al}, RGB/8)${isDirtyDoc(d)?' *':''}`,h('span',{class:'x',title:'닫기',onclick:e=>{e.stopPropagation();closeDoc(d)}},'✕'));el.onclick=()=>{if(d!==doc){switchDoc(d)}};el.onauxclick=e=>{if(e.button===1)closeDoc(d)};t.append(el)}$('#empty').hidden=!!doc;updateStatus()}
function updateStatus(){if(!doc){$('#stDoc').textContent='';$('#zoomInp').value='';return}const flatB=doc.w*doc.h*3;let lb=0;flat().forEach(l=>{if(l.canvas)lb+=l.canvas.width*l.canvas.height*4});$('#stDoc').textContent=`문서: ${fmtMB(flatB)}/${fmtMB(lb)}  ·  ${doc.w} × ${doc.h} 픽셀 (${doc.dpi} ppi)`;updateZoomUI()}

/* ===== 패널 ===== */
function showTab(k){const tb=$(`.ptab[data-tab="${k}"]`);if(!tb)return;const g=tb.closest('.pgroup');g.querySelectorAll('.ptab').forEach(x=>x.classList.toggle('on',x===tb));g.querySelectorAll('.pbody').forEach(b=>b.hidden=b.dataset.body!==k);if(innerWidth<=900)document.body.classList.add('showPanels');refreshAll();schedulePanels()}
$$('.ptab').forEach(t=>t.onclick=()=>showTab(t.dataset.tab));
function refreshAll(){renderTabs();refreshLayers();refreshHistory();refreshProps();refreshChannels();refreshChar();refreshPara();refreshBrush();refreshAdj();updateInfo(null)}

