function drawThumb(cv,src,x,y,full){const g=cx(cv);g.clearRect(0,0,cv.width,cv.height);if(!src||!doc)return;const W=full?doc.w:src.width,H=full?doc.h:src.height;const s=Math.min(cv.width/W,cv.height/H);const ox=(cv.width-W*s)/2,oy=(cv.height-H*s)/2;g.imageSmoothingQuality='low';if(full)g.drawImage(src,ox+x*s,oy+y*s,src.width*s,src.height*s);else g.drawImage(src,ox,oy,W*s,H*s)}
