    const pad=h('div',{style:`width:${depth*14}px;flex:none`});const fold=l.type==='group'?h('div',{class:'lfold',html:icon(l.open?'chevD':'chevR','i s'),onclick:e=>{e.stopPropagation();l.open=!l.open;refreshLayers()}}):h('div',{class:'lfold'});
