function keyOf(e){const c=e.code||'';if(c.startsWith('Key'))return c.slice(3).toLowerCase();if(c.startsWith('Digit'))return c.slice(5);if(c.startsWith('Numpad')&&/\d$/.test(c))return c.slice(-1);const m={BracketLeft:'[',BracketRight:']',Backslash:'\\',Equal:'=',Minus:'-',NumpadAdd:'=',NumpadSubtract:'-',Space:' ',Comma:',',Period:'.',Slash:'/',Semicolon:';',Quote:"'",Backquote:'`'};if(m[c])return m[c];const k=e.key||'';return k.length===1?k.toLowerCase():k}
