    if(K==='m')return run(ADJ.curves);if(K==='u'&&sh)return run(ADJ.desat);if(K==='u')return run(ADJ.hueSat);
    if(K==='b'&&sh&&alt)return run(ADJ.bw);if(K==='b'&&sh)return run(ADJ.autoColor);if(K==='b')return run(ADJ.colorBal);
