    if(K===',')return run(()=>{const l=doc.active;if(l){l.visible=!l.visible;markDirty();refreshLayers()}});
    if(K==='/')return run(()=>{const l=doc.active;if(l&&!l.isBg){l.locked=!l.locked;pushHist('레이어 잠금')}});
    if(K==='0'&&alt)return run(()=>fitView(true));if(K==='0')return run(()=>fitView());if(K==='1')return run(()=>fitView(true));
    if(K==='=')return run(()=>zoomStep(1));if(K==='-')return run(()=>zoomStep(-1));
    if('2345'.includes(K)&&K.length===1){doc.channel={2:'rgb',3:'r',4:'g',5:'b'}[K];chanCache=null;requestDraw();refreshChannels();return run(()=>{})}
    if(K===']'&&sh)return run(()=>cmdArrange('front'));if(K===']')return run(()=>cmdArrange('fwd'));if(K==='['&&sh)return run(()=>cmdArrange('back'));if(K==='[')return run(()=>cmdArrange('bwd'));
