  if(K==='['||K===']'){e.preventDefault();if(sh){opts.hard=clamp(opts.hard+(K===']'?.25:-.25),0,1)}else{const s=opts.size;const st=s<10?1:s<50?5:s<100?10:s<200?25:50;opts.size=clamp(s+(K===']'?st:-st),1,2500)}renderOptions();requestDraw();refreshBrush();return}
  if(/^[0-9]$/.test(K)&&tool&&(tool.brushCursor||tool.id==='gradient'||tool.id==='bucket'||tool.group==='shape')){e.preventDefault();const v=K==='0'?1:+K/10;if(sh&&tool.brushCursor)opts.flow=v;else opts.opacity=v;renderOptions();return}
  if(/^[0-9]$/.test(K)&&doc&&doc.active&&!alt){e.preventDefault();doc.active.opacity=K==='0'?1:+K/10;markDirty();refreshLayers();lHist('불투명도');return}
