function sampleDoc(){const d=createDoc('시작 샘플.psd',1560,944,{dpi:72});const prev=doc;doc=d;const bgc=mkCanvas(1560,944);let g=cx(bgc);const gr=g.createLinearGradient(0,0,1560,944);gr.addColorStop(0,'#eef2f7');gr.addColorStop(1,'#d7e0ec');g.fillStyle=gr;g.fillRect(0,0,1560,944);const bgL=newLayer({name:'배경',canvas:bgc,isBg:true});
  const card=mkCanvas(1560,944);g=cx(card);g.fillStyle='#ffffff';g.shadowColor='rgba(30,50,80,.18)';g.shadowBlur=40;g.shadowOffsetY=12;g.beginPath();g.roundRect?g.roundRect(330,190,900,560,22):g.rect(330,190,900,560);g.fill();const cardL=newLayer({name:'카드',canvas:card});
  const dot=mkCanvas(1560,944);g=cx(dot);const rg=g.createRadialGradient(1180,250,10,1180,250,260);rg.addColorStop(0,'rgba(45,123,229,.9)');rg.addColorStop(1,'rgba(45,123,229,0)');g.fillStyle=rg;g.fillRect(0,0,1560,944);const dotL=newLayer({name:'빛 번짐',canvas:dot,blend:'multiply',opacity:.55});
  const mkT=(str,size,color,x,y,bold)=>{const l=newLayer({type:'text',name:str.split('\n')[0],text:{str,font:'Pretendard',size,color,bold,italic:false,align:'left',lh:1.3,x,y}});rasterizeText(l);return l};
  const t1=mkT('IUX Photo',96,'#1b2a3f',410,280,true),t2=mkT('PSD · JPG · PNG · WEBP · TIF 파일을\n이 창에 끌어다 놓으면 바로 열립니다',34,'#43536b',414,430,false),t3=mkT('레이어 · 마스크 · 혼합 모드를 그대로 PSD로 저장합니다',24,'#2d7be5',416,620,false);
  const grp=newGroup('안내 문구',[t3,t2,t1]);grp.open=true;d.root.children=[bgL,cardL,dotL,grp];d.active=t1;doc=prev;addDoc(d)}
async function init(){try{const c=localStorage.getItem('iuxPaste');if(c)document.documentElement.style.setProperty('--paste',c)}catch(e){}buildMenubar();setTool('move');try{await document.fonts.load('700 20px Pretendard','가A');await document.fonts.load('400 20px Pretendard','가A')}catch(e){}resizeView();new ResizeObserver(()=>{const cxp=doc?toDoc(VW/2,VH/2):null;resizeView();if(doc&&cxp){doc.panX=VW/2-cxp.x*doc.zoom;doc.panY=VH/2-cxp.y*doc.zoom;clampPan()}requestDraw();schedulePanels()}).observe(work);sampleDoc();restoreFonts();dlReady.then(dl=>{ONLINE=!!dl;$('#envTag').textContent=dl?'온라인 · 파일은 이 브라우저 안에서만 처리됩니다':'로컬 실행 · 파일은 이 브라우저 안에서만 처리됩니다'});if(!window.claude)$('#envTag').textContent='로컬 실행 · 파일은 이 브라우저 안에서만 처리됩니다';if(typeof agPsd==='undefined')toast('PSD 해석기를 불러오지 못했습니다. 인터넷 연결을 확인하세요.',5000)}
